#!/usr/bin/env bash
# 3x-ui-pro-multi: standalone installer based on github.com/mozaroc/3x-ui-pro.
# Includes the complete source bundle; --extract-only lets you inspect it.
set -Eeuo pipefail

usage() {
    cat <<'HELP'
3x-ui-pro-multi / 3x-ui 3.8.5

Install on a fresh Debian 12/13 or Ubuntu 24.04/26.04 VPS:
  sudo bash x-ui-latest.sh
  sudo bash x-ui-latest.sh -subdomain panel.example.com -reality_domain r.example.com

Optional protocol ports:
  -hy2_port 443  -ss_port 8388

Apply the bundled patch to an installation of this build:
  sudo bash x-ui-latest.sh --patch

Extract all sources to a NEW directory without installing anything:
  bash x-ui-latest.sh --extract-only ./review-source

Download this file first; process substitution / piping to bash is unsupported.
HELP
}

if [[ "${1:-}" == --help || "${1:-}" == -h ]]; then
    usage
    exit 0
fi

mode=install
script=x-ui-latest.sh
extract_destination=''
if [[ "${1:-}" == --extract-only ]]; then
    [[ $# == 2 && -n "$2" ]] || { usage >&2; exit 2; }
    mode=extract
    extract_destination=$2
    [[ ! -e "$extract_destination" && ! -L "$extract_destination" ]] || {
        echo 'Extraction destination must not already exist.' >&2; exit 1;
    }
elif [[ "${1:-}" == --patch ]]; then
    script=x-ui-patch.sh
    shift
fi

if [[ "$mode" == install && $EUID -ne 0 ]]; then
    echo 'Run with sudo bash x-ui-latest.sh (or as root).' >&2
    exit 1
fi

source_file=${BASH_SOURCE[0]}
[[ -f "$source_file" ]] || { echo 'Download the script to a regular file first.' >&2; exit 1; }
for dependency in awk base64 sha256sum tar mktemp; do
    command -v "$dependency" >/dev/null || { echo "Missing command: $dependency" >&2; exit 1; }
done

stage=$(mktemp -d -t 3x-ui-pro-multi.XXXXXXXX)
cleanup() { [[ -z "${stage:-}" ]] || rm -rf -- "$stage"; }
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
awk 'payload && /^# / { print substr($0, 3) } $0 == "# __3X_UI_MULTI_PAYLOAD__" { payload=1 }' \
    "$source_file" | base64 --decode > "$stage/payload.tar.gz"
printf '%s  %s\n' 'bcd4e29f81f20f97d7b3f6919d05c4917f899eda2bb6a0ce2824980e7a2ef127' "$stage/payload.tar.gz" | sha256sum --check --status || {
    echo 'Embedded archive checksum mismatch. Download the complete script again.' >&2; exit 1;
}
mkdir "$stage/source"
tar -xzf "$stage/payload.tar.gz" --no-same-owner -C "$stage/source"

if [[ "$mode" == extract ]]; then
    mkdir -m 700 -- "$extract_destination"
    cp -R "$stage/source/3x-ui-pro-multi/." "$extract_destination/"
    printf 'Sources extracted to: %s\n' "$extract_destination"
else
    bash "$stage/source/3x-ui-pro-multi/$script" "$@"
fi
exit 0
